import React from 'react';
import { Activity, AlertTriangle, CheckCircle2, ChevronRight, CreditCard, Download, FileText, LockKeyhole, ShieldCheck, Store } from 'lucide-react';

const activity = [
  ['Shop approved', 'Chennai Main was approved by Super Admin', '2 min ago', 'success'],
  ['Admin account updated', 'Rajesh Kumar changed access permissions', '18 min ago', 'info'],
  ['Security alert', 'Failed login attempt from a new device', '42 min ago', 'warning'],
  ['Billing sync completed', 'Monthly plan reconciliation finished', '1 hr ago', 'success'],
  ['Shop blocked', 'Salem Outlet access was temporarily blocked', '3 hrs ago', 'danger'],
];

function Shell({ eyebrow, title, description, children, action }) { return <div className="dashboard-container super-control-page"><div className="control-hero"><div><span className="control-eyebrow">{eyebrow}</span><h1>{title}</h1><p>{description}</p></div>{action}</div>{children}</div>; }
function MiniCard({ icon: Icon, label, value, note, tone = 'violet' }) { return <div className="control-mini-card"><span className={`control-mini-icon ${tone}`}><Icon size={18} /></span><div><small>{label}</small><strong>{value}</strong><em>{note}</em></div></div>; }

export function SuperActivity() { return <Shell eyebrow="Governance & compliance" title="Activity log" description="A complete trail of admin actions, shop changes and security events." action={<button className="super-ghost-btn control-light-btn"><Download size={15} /> Export log</button>}><div className="control-card-grid"><MiniCard icon={Activity} label="Events today" value="128" note="+24 from yesterday" /><MiniCard icon={ShieldCheck} label="Security score" value="96 / 100" note="Healthy posture" tone="green" /><MiniCard icon={AlertTriangle} label="Needs review" value="4" note="2 high priority" tone="orange" /></div><div className="control-panel activity-panel"><div className="control-panel-head"><div><h3>Recent activity</h3><p>All network events are recorded with time and context.</p></div><div className="activity-filter"><select><option>All activity</option><option>Security</option><option>Shop changes</option></select></div></div>{activity.map(([title,description,time,tone])=><div className="activity-row" key={title + time}><span className={`activity-icon ${tone}`}>{tone === 'success' ? <CheckCircle2 size={17} /> : tone === 'warning' ? <AlertTriangle size={17} /> : tone === 'danger' ? <LockKeyhole size={17} /> : <Activity size={17} />}</span><span><strong>{title}</strong><small>{description}</small></span><time>{time}</time><ChevronRight size={15} /></div>)}</div></Shell>; }

export function SuperBilling() { return <Shell eyebrow="Platform finance" title="Billing & subscriptions" description="Track plan adoption, invoices and network-level subscription health." action={<button className="super-primary-btn"><FileText size={15} /> View invoices</button>}><div className="control-card-grid"><MiniCard icon={CreditCard} label="Monthly recurring revenue" value="₹2.84L" note="+14.2% this month" /><MiniCard icon={Store} label="Paid shops" value="42" note="84% of all shops" tone="cyan" /><MiniCard icon={AlertTriangle} label="Past due" value="3" note="₹18,400 outstanding" tone="orange" /></div><div className="control-panel"><div className="control-panel-head"><div><h3>Subscription overview</h3><p>Plans currently assigned to your shops</p></div><button className="panel-link">Manage plans <ChevronRight size={14} /></button></div><div className="billing-plan-grid">{[['Starter','24 shops','₹72,000','violet'],['Growth','14 shops','₹98,000','cyan'],['Enterprise','4 shops','₹1,14,000','orange']].map(([name,shops,revenue,tone])=><div className="billing-plan" key={name}><span className={`billing-plan-icon ${tone}`}><CreditCard size={17} /></span><strong>{name}</strong><small>{shops}</small><b>{revenue}<em>/ month</em></b><div className="plan-progress"><i style={{width:name==='Starter'?'68%':name==='Growth'?'43%':'22%'}} /></div></div>)}</div></div></Shell>; }
